from pyspark.sql import functions as F


def save(observations, path):
    # Save the readings at `path`, one folder per New York date.
    pass


def solve(observations):
    path = "/tmp/weather/new_york_days"
    save(observations, path)
    files = spark.read.schema("observation_id STRING, station_id STRING, observed_at TIMESTAMP, temperature_c DOUBLE, local_date DATE").parquet(path)
    # Which folder each reading was found in, such as local_date=2026-03-07.
    return files.select("*", F.regexp_extract("_metadata.file_path", r"/(local_date=[^/]*)/", 1).alias("folder"))
